import {FeatureFlagProvider} from '@github-ui/react-core/feature-flag-provider'
import {PageBannerOutlet} from '@github-ui/page-banner'
import {CustomModelsTab} from './components/CustomModelsTab'
import {Header} from './components/Header'
import type {CustomModelsIndexPayload} from './types'
import {ProvidersProvider} from '@github-ui/copilot-byok/providers/react'

export function CopilotByokEnterpriseSettings({
  enabledFeatures,
  enterpriseSlug,
  publicKey,
  customKeys,
  customModelPolicy,
  customModels,
  showAiControls,
  tab,
  availableProviders,
}: CustomModelsIndexPayload) {
  return (
    <FeatureFlagProvider features={enabledFeatures ?? {}}>
      <ProvidersProvider providers={availableProviders}>
        <PageBannerOutlet />
        <Header enterpriseSlug={enterpriseSlug} showAiControls={showAiControls} tab={tab} />
        {tab === 'custom-models' && (
          <CustomModelsTab
            publicKey={publicKey}
            customKeys={customKeys}
            customModels={customModels}
            enterpriseSlug={enterpriseSlug}
            customModelPolicy={customModelPolicy}
          />
        )}
      </ProvidersProvider>
    </FeatureFlagProvider>
  )
}

try{ CopilotByokEnterpriseSettings.displayName ||= 'CopilotByokEnterpriseSettings' } catch {}