import {getMaybeJSONErrorMessage} from '@github-ui/copilot-byok-settings/helpers/extract-errors'
import {ResponseError} from '@github-ui/react-core/future/response-error'
import type {UseMutationOptions} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

// TODO: Maybe we can use zod for this too
export type UpdateCustomKeyPayload = {
  name?: string
  api_key?: string | null
} & (
  | {
      deployment_url?: string | null
    }
  | {
      models?: Array<{slug: string; name?: string | null}>
    }
)

export function updateCustomKeyMutationOptions({
  enterpriseSlug,
  customKeyId,
}: {
  enterpriseSlug: string
  customKeyId: number
}): UseMutationOptions<void, ResponseError, UpdateCustomKeyPayload> {
  return {
    async mutationFn(variables) {
      const req = await reactFetchJSON(`/enterprises/${enterpriseSlug}/settings/copilot/custom-keys/${customKeyId}`, {
        method: 'PUT',
        body: variables,
      })
      if (!req.ok) {
        const message = await getMaybeJSONErrorMessage(req)
        throw new ResponseError(message || 'Failed to update custom key', req)
      }
    },
  }
}
