import {ProviderLogo} from '@github-ui/copilot-byok/providers/ProviderLogo'
import {useMutation} from '@github-ui/react-query'
import {ActionList, ActionMenu, Stack} from '@primer/react'
import {clsx} from 'clsx'
import {useCallback, useId} from 'react'

import styles from './AvailableModel.module.css'
import type {CustomKey, CustomModel} from '@github-ui/copilot-byok-settings/types'
import {updateCustomModelMutationOptions} from '../queries/update-custom-model'
import type {EnterpriseCustomModelAccessStatus} from '../types'
import {ModelConfigurationDialog} from './ModelConfigurationDialog'

interface AvailableModelProps {
  customKey: CustomKey
  modelAccessStatus?: EnterpriseCustomModelAccessStatus
  model: CustomModel
  enterpriseSlug: string
  onUpdateModel: () => void
}

export function AvailableModel({
  customKey,
  modelAccessStatus,
  model,
  onUpdateModel,
  enterpriseSlug,
}: AvailableModelProps) {
  const id = useId()
  const labelId = `${id}-label`
  const errorId = `${id}-error`
  const {mutate, isPending: busy, error} = useMutation(updateCustomModelMutationOptions(enterpriseSlug))
  const updateEnabled = useCallback(
    (enabled: boolean) => {
      mutate({...model, id: model.id, enabled}, {onSuccess: onUpdateModel})
    },
    [model, mutate, onUpdateModel],
  )
  const onEnable = useCallback(() => updateEnabled(true), [updateEnabled])
  const onDisable = useCallback(() => updateEnabled(false), [updateEnabled])
  const modelDescription = modelDescriptionForScreenReader(model, customKey)

  return (
    <div className={clsx(styles.AvailableModel, 'Box-row--hover-gray')}>
      <Stack.Item grow>
        <span id={labelId} className={styles.AvailableModelName}>
          <ProviderLogo provider={customKey.provider} className={styles.AvailableModelLogo} />
          <span data-area="model_name">{model.name ?? model.slug}</span>
          <span data-area="key_name">{customKey.name}</span>
        </span>
        {error && (
          <span id={errorId} className="color-fg-danger ml-4">
            {error.message}
          </span>
        )}
      </Stack.Item>
      <ModelConfigurationDialog
        enterpriseSlug={enterpriseSlug}
        onUpdateModel={onUpdateModel}
        model={model}
        modelAccessStatus={modelAccessStatus}
        customKeyName={customKey.name}
      />
      <ActionMenu>
        <ActionMenu.Button
          aria-label={`${modelDescription} status: ${model.enabled ? 'Enabled' : 'Disabled'}`}
          aria-describedby={error ? errorId : undefined}
        >
          {model.enabled ? 'Enabled' : 'Disabled'}
        </ActionMenu.Button>
        <ActionMenu.Overlay width="medium" align="end">
          <ActionList selectionVariant="single">
            <ActionList.Item selected={model.enabled} onSelect={onEnable} loading={busy}>
              Enabled <span className="sr-only">{modelDescription}</span>
              <ActionList.Description variant="block">
                This model is always enabled. Organizations cannot disable it.
              </ActionList.Description>
            </ActionList.Item>
            <ActionList.Item selected={!model.enabled} onSelect={onDisable} loading={busy}>
              Disabled <span className="sr-only">{modelDescription}</span>
              <ActionList.Description variant="block">
                This model is always disabled. Organizations cannot enable it.
              </ActionList.Description>
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </div>
  )
}

function modelDescriptionForScreenReader(
  model: Pick<CustomModel, 'name' | 'slug' | 'editable'>,
  customKey: Pick<CustomKey, 'name' | 'ownerName'>,
) {
  const suffix = model.editable ? '' : ` provided by ${customKey.ownerName}`
  return `${model.name ?? model.slug} from ${customKey.name}${suffix}`
}

try{ AvailableModel.displayName ||= 'AvailableModel' } catch {}