import {FormControl, Stack, TextInput} from '@primer/react'
import {useId} from 'react'
import * as z from 'zod'

import {ProviderModelSelectorPane} from '../ProviderModelSelectorPane'
import type {ProviderFieldProps} from '../types'
import {useAPIKey} from '@github-ui/copilot-byok-settings/hooks/use-api-key'
import {FormValidationNode} from '@github-ui/copilot-byok-settings/components/FormValidationNode'
import styles from '../../AddApiKeyDialog.module.css'

export const awsBedrockFormSchema = {
  provider: z.literal('awsbedrock'),
  access_key: z.string().min(1, 'Access Key is required'),
  models: z
    .array(
      z.union([
        z.object({
          id: z.number(),
          name: z.string().nullish(),
        }),
        z.object({
          slug: z.string(),
          name: z.string().nullish(),
        }),
      ]),
    )
    .min(1, 'Please select a model'),
} as const

export function AwsBedrockFields({
  apiKey,
  publicKey,
  customKey,
  validation,
  isPending,
  setValidation,
  onSetAdditionalData,
  enterpriseSlug,
}: ProviderFieldProps<'awsbedrock'>) {
  const id = useId()
  const [accessKey, setAccessKey] = useAPIKey(publicKey || '')
  const accessKeyValidationId = `access_key-validation-${id}`
  const htmlForId = `${id}-model-selector`
  const ariaDescribedBy = `${id}-description`

  return (
    <>
      <FormControl required disabled={isPending}>
        <FormControl.Label>Access Key</FormControl.Label>
        <TextInput
          name="access_key"
          data-1p-ignore
          type="password"
          autoComplete="new-password"
          className="width-full"
          aria-describedby={accessKeyValidationId}
          onBlur={e => setAccessKey(e.currentTarget.value)}
        />
        <FormValidationNode item={validation?.access_key} id={accessKeyValidationId} />
      </FormControl>

      <Stack.Item grow className={styles.ModelSelectorLayout}>
        <FormControl className="width-full" disabled={isPending}>
          <FormControl.Label htmlFor={htmlForId}>Available models</FormControl.Label>
          <ProviderModelSelectorPane
            provider="awsbedrock"
            customKeyId={customKey?.id}
            key={`awsbedrock-${apiKey}`}
            apiKey={apiKey}
            providerData={{
              provider: 'awsbedrock',
              accessKey: accessKey || '',
            }}
            isPending={isPending}
            htmlForId={htmlForId}
            aria-describedby={ariaDescribedBy}
            setValidation={setValidation}
            onSetAdditionalData={onSetAdditionalData}
            enterpriseSlug={enterpriseSlug}
          />
          <FormValidationNode item={validation?.models} id={ariaDescribedBy} />
        </FormControl>
      </Stack.Item>
    </>
  )
}

try{ AwsBedrockFields.displayName ||= 'AwsBedrockFields' } catch {}