import {useState} from 'react'
import {Banner, Link, SegmentedControl, Stack} from '@primer/react'
import styles from './CustomModelsTab.module.css'
import type {CustomKey, CustomModel} from '@github-ui/copilot-byok-settings/types'
import {useCustomModelsQuery} from '../queries/use-custom-models-query'
import {AddApiKeyButton} from './AddApiKeyButton'
import {ApiKeys} from './ApiKeys'
import {AvailableModels} from './AvailableModels'
import type {CustomModelPolicy} from '../types'

type SubTab = 'keys' | 'models'

export function CustomModelsTab({
  publicKey,
  customKeys: initialCustomKeys,
  customModels: initialCustomModels,
  enterpriseSlug,
  customModelPolicy: initialCustomModelPolicy,
}: {
  publicKey: [version: number, base64EncodedKey: string]
  customKeys: CustomKey[]
  customModels: CustomModel[]
  enterpriseSlug: string
  customModelPolicy: CustomModelPolicy
}) {
  const [selectedSubTab, setSelectedSubTab] = useState<SubTab>('keys')
  const {data, refetch} = useCustomModelsQuery({
    enterpriseSlug,
    initialData: {
      customKeys: initialCustomKeys,
      customModels: initialCustomModels,
      customModelPolicy: initialCustomModelPolicy,
    },
  })

  const customKeys = data?.customKeys ?? []
  const customModels = data?.customModels ?? []
  const hasKeys = customKeys.length > 0
  const customModelPolicy = data?.customModelPolicy ?? {}

  return (
    <>
      <p className="color-fg-muted">
        Add API keys from Al model providers to register custom third-party models. Once added, you can enable custom
        models to be used with specific GitHub features. When using custom models, GitHub will share your data,
        including code, with the third-party model provider using your provided API key. Use of the model is further
        subject to the terms and privacy policy of the third-party model provider.
      </p>
      <Banner title="Custom model access" hideTitle className="mb-3">
        <p className="mb-0">
          If preview features are enabled, you agree to pre-release terms.{' '}
          <Link inline href="https://docs.github.com/copilot/how-tos/use-ai-models">
            Learn about the supported AI models in GitHub Copilot
          </Link>
          .
        </p>
      </Banner>
      <div className="border rounded-top-2 overflow-hidden">
        <div className={styles.segmentedControlAndActions}>
          <SegmentedControl aria-label="Custom models navigation">
            <SegmentedControl.Button onClick={() => setSelectedSubTab('keys')} selected={selectedSubTab === 'keys'}>
              API keys
            </SegmentedControl.Button>
            <SegmentedControl.Button onClick={() => setSelectedSubTab('models')} selected={selectedSubTab === 'models'}>
              Added models
            </SegmentedControl.Button>
          </SegmentedControl>
          {hasKeys && (
            <AddApiKeyButton onSuccess={() => refetch()} publicKey={publicKey[1]} enterpriseSlug={enterpriseSlug} />
          )}
        </div>
      </div>
      <Stack gap="none" className="border border-top-0 rounded-bottom-2">
        {selectedSubTab === 'keys' ? (
          <ApiKeys
            customKeys={customKeys}
            publicKey={publicKey[1]}
            onRefresh={() => refetch()}
            enterpriseSlug={enterpriseSlug}
          />
        ) : (
          <AvailableModels
            customKeys={customKeys}
            customModels={customModels}
            onUpdateModels={() => refetch()}
            enterpriseSlug={enterpriseSlug}
            publicKey={publicKey[1]}
            customModelPolicy={customModelPolicy}
          />
        )}
      </Stack>
    </>
  )
}

try{ CustomModelsTab.displayName ||= 'CustomModelsTab' } catch {}