import {ActionList, FormControl, RadioGroup, Radio, Spinner, TextInput} from '@primer/react'
import {SearchIcon} from '@primer/octicons-react'
import {useDebounce} from '@github-ui/use-debounce'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {type ChangeEventHandler, type Dispatch, type SetStateAction, useCallback, useMemo, useState} from 'react'
import {useOrgsQuery} from '../queries/use-orgs-query'
import {useSearchOrgsQuery} from '../queries/use-search-orgs-query'
import type {EnterpriseCustomModelAccessStatus, Organization} from '../types'

export function ModelOrgAccessControls({
  className,
  enterpriseSlug,
  modelAccessStatus,
  modelId,
}: {
  className?: string
  enterpriseSlug: string
  modelAccessStatus?: EnterpriseCustomModelAccessStatus
  modelId: number | undefined
}) {
  const [query, setQuery] = useState('')
  const [allowAllOrgsAccess, setAllowAllOrgsAccess] = useState(modelAccessStatus?.enabledForAllOrgs ?? false)
  const showPerOrgControls = !allowAllOrgsAccess
  const [queryForSearch, setQueryForSearch] = useState(query)
  const debouncedSetQueryForSearch = useDebounce(setQueryForSearch, 1000)
  const onQueryChange = useCallback<ChangeEventHandler<HTMLInputElement>>(
    evt => {
      const newValue = evt.currentTarget.value
      setQuery(newValue)
      debouncedSetQueryForSearch(newValue)
    },
    [debouncedSetQueryForSearch],
  )
  const {data: allOrgs, isPending: isLoadingAllOrgs, error: allOrgsError} = useOrgsQuery({enterpriseSlug})
  const {
    data: searchResults,
    isPending: isSearching,
    error: searchError,
  } = useSearchOrgsQuery({enterpriseSlug, query: queryForSearch, modelId})
  const initiallySelectedOrgIds = useMemo(
    () => new Set(modelAccessStatus?.allowedOrgIds),
    [modelAccessStatus?.allowedOrgIds],
  )
  const [selectedOrgIds, setSelectedOrgIds] = useState(initiallySelectedOrgIds)
  const initiallySelectedOrgs = useMemo(
    () => (allOrgs ?? []).filter(org => initiallySelectedOrgIds.has(org.id)),
    [allOrgs, initiallySelectedOrgIds],
  )
  const initiallyDeselectedOrgs = useMemo(
    () => (allOrgs ?? []).filter(org => !initiallySelectedOrgIds.has(org.id)),
    [allOrgs, initiallySelectedOrgIds],
  )

  return (
    <div className={className}>
      <p className="mb-3 px-3">Select which organizations should have access to this model.</p>
      <RadioGroup name="orgAccessLimitType" className="mx-3 mb-3">
        <RadioGroup.Label visuallyHidden>How should organization access be limited?</RadioGroup.Label>
        <FormControl>
          <Radio
            value="1"
            onChange={() => setAllowAllOrgsAccess(true)}
            name="allOrgsAccessSetting"
            checked={allowAllOrgsAccess}
          />
          <FormControl.Label>Allow for all organizations</FormControl.Label>
        </FormControl>
        <FormControl>
          <Radio
            value=""
            onChange={() => setAllowAllOrgsAccess(false)}
            name="allOrgsAccessSetting"
            checked={!allowAllOrgsAccess}
          />
          <FormControl.Label>Choose per organization</FormControl.Label>
          {!allowAllOrgsAccess && <FormControl.Caption>{selectedOrgIds.size} selected</FormControl.Caption>}
        </FormControl>
      </RadioGroup>
      {showPerOrgControls && (
        <>
          <input name="allowedOrgIds" type="hidden" value={[...selectedOrgIds].join(',')} />
          <FormControl className="mx-3 mb-3" disabled={isLoadingAllOrgs}>
            <FormControl.Label visuallyHidden>Search organizations by name</FormControl.Label>
            <TextInput
              leadingVisual={SearchIcon}
              block
              loading={isSearching && queryForSearch.trim().length > 0}
              value={query}
              onChange={onQueryChange}
              placeholder="Search organizations by name"
            />
            {searchError && <FormControl.Validation variant="error">{searchError.message}</FormControl.Validation>}
          </FormControl>
          <ActionList className="pt-0" selectionVariant="multiple" role="menu">
            {searchResults ? (
              <>
                <ActionList.GroupHeading>Search results</ActionList.GroupHeading>
                <ActionList.Group aria-label="Search results" role="menu">
                  {searchResults.map(org => (
                    <OrgActionListItem
                      key={org.id}
                      disabled={allowAllOrgsAccess}
                      org={org}
                      selected={selectedOrgIds.has(org.id)}
                      setSelectedOrgIds={setSelectedOrgIds}
                    />
                  ))}
                </ActionList.Group>
                {searchResults.length < 1 && <ActionList.Item disabled>No organizations match</ActionList.Item>}
                {initiallySelectedOrgs.length > 0 && (
                  <>
                    <ActionList.Divider />
                    <ActionList.GroupHeading>Allowed organizations</ActionList.GroupHeading>
                    <ActionList.Group aria-label="Allowed organizations" role="menu">
                      {initiallySelectedOrgs.map(org => (
                        <OrgActionListItem
                          key={org.id}
                          disabled={allowAllOrgsAccess}
                          org={org}
                          selected={selectedOrgIds.has(org.id)}
                          setSelectedOrgIds={setSelectedOrgIds}
                        />
                      ))}
                    </ActionList.Group>
                  </>
                )}
              </>
            ) : (
              <>
                {isLoadingAllOrgs && <Spinner className="ml-3" />}
                {allOrgsError && (
                  <ActionList.GroupHeading>
                    <span className="color-fg-danger">{allOrgsError.message}</span>
                  </ActionList.GroupHeading>
                )}
                {initiallySelectedOrgs.length > 0 && (
                  <ActionList.GroupHeading>Allowed organizations</ActionList.GroupHeading>
                )}
                <ActionList.Group aria-label="Allowed organizations" role="menu">
                  {initiallySelectedOrgs.map(org => (
                    <OrgActionListItem
                      key={org.id}
                      disabled={allowAllOrgsAccess}
                      org={org}
                      selected={selectedOrgIds.has(org.id)}
                      setSelectedOrgIds={setSelectedOrgIds}
                    />
                  ))}
                </ActionList.Group>
                {initiallySelectedOrgs.length > 0 && initiallyDeselectedOrgs.length > 0 && (
                  <ActionList.GroupHeading>Other organizations</ActionList.GroupHeading>
                )}
                <ActionList.Group
                  aria-label={initiallySelectedOrgs.length > 0 ? 'Other organizations' : 'Organizations'}
                  role="menu"
                >
                  {initiallyDeselectedOrgs.map(org => (
                    <OrgActionListItem
                      key={org.id}
                      disabled={allowAllOrgsAccess}
                      org={org}
                      selected={selectedOrgIds.has(org.id)}
                      setSelectedOrgIds={setSelectedOrgIds}
                    />
                  ))}
                </ActionList.Group>
              </>
            )}
          </ActionList>
        </>
      )}
    </div>
  )
}

function OrgActionListItem({
  org,
  disabled,
  selected,
  setSelectedOrgIds,
}: {
  org: Organization
  disabled?: boolean
  selected: boolean
  setSelectedOrgIds: Dispatch<SetStateAction<Set<number>>>
}) {
  const onSelect = useCallback(() => {
    if (selected) {
      setSelectedOrgIds(prev => {
        const newVal = new Set(prev)
        newVal.delete(org.id)
        return newVal
      })
    } else {
      setSelectedOrgIds(prev => new Set(prev).add(org.id))
    }
  }, [org.id, selected, setSelectedOrgIds])
  return (
    <ActionList.Item
      onSelect={onSelect}
      aria-checked={selected}
      role="menuitemcheckbox"
      key={org.id}
      disabled={disabled}
      selected={selected}
    >
      <ActionList.LeadingVisual>
        <GitHubAvatar square src={org.avatarUrl} />
      </ActionList.LeadingVisual>
      {org.name}
    </ActionList.Item>
  )
}

try{ ModelOrgAccessControls.displayName ||= 'ModelOrgAccessControls' } catch {}
try{ OrgActionListItem.displayName ||= 'OrgActionListItem' } catch {}