import {useQuery} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {Organization} from '../types'
import {getMaybeJSONErrorMessage} from '@github-ui/copilot-byok-settings/helpers/extract-errors'

type OrganizationsPayload = Organization[]

export function useSearchOrgsQuery({
  enterpriseSlug,
  query: filter,
  modelId,
}: {
  enterpriseSlug: string
  query: string
  modelId?: number
}) {
  const queryKey = ['byok-settings', 'orgs', enterpriseSlug, filter, modelId]
  const query = useQuery({
    queryKey,
    queryFn: async (): Promise<OrganizationsPayload> => {
      const url = `/enterprises/${enterpriseSlug}/settings/copilot/custom-model-orgs?q=${encodeURIComponent(filter)}`
      const response = await verifiedFetch(url, {headers: {Accept: 'application/json'}})
      if (!response.ok) {
        const errorMessage = await getMaybeJSONErrorMessage(response)
        const fallbackMessage = `Failed to search organizations for enterprise ${enterpriseSlug}`
        throw new Error(errorMessage ?? fallbackMessage)
      }
      const result = await response.json()
      return result as OrganizationsPayload
    },
    enabled: filter.trim().length > 0 && enterpriseSlug.trim().length > 0,
  })
  return {...query, queryKey}
}
