import {Breadcrumbs} from '@primer/react'

interface ModelsBreadcrumbsProps {
  enterpriseSlug: string
  showAiControls?: boolean
}

export function ModelsBreadcrumbs({enterpriseSlug, showAiControls}: ModelsBreadcrumbsProps) {
  if (showAiControls) {
    return (
      <Breadcrumbs>
        <Breadcrumbs.Item href={`/enterprises/${enterpriseSlug}/ai-controls/copilot`}>Copilot</Breadcrumbs.Item>
        <Breadcrumbs.Item href={`/enterprises/${enterpriseSlug}/ai-controls/copilot/models`} selected>
          Models
        </Breadcrumbs.Item>
      </Breadcrumbs>
    )
  }

  return (
    <Breadcrumbs>
      <Breadcrumbs.Item href={`/enterprises/${enterpriseSlug}/settings/policies/code`}>Policies</Breadcrumbs.Item>
      <Breadcrumbs.Item href={`/enterprises/${enterpriseSlug}/settings/copilot`}>Copilot</Breadcrumbs.Item>
      <Breadcrumbs.Item href={`/enterprises/${enterpriseSlug}/settings/copilot/models`} selected>
        Models
      </Breadcrumbs.Item>
    </Breadcrumbs>
  )
}

try{ ModelsBreadcrumbs.displayName ||= 'ModelsBreadcrumbs' } catch {}